func TestVectorE6MustSetRandom(t *testing.T) {
	vector := make(VectorE6, 17)
	vector.MustSetRandom()

	var zero E6
	for i := range vector {
		require.False(t, vector[i].Equal(&zero), "element %d was left zero", i)
		for j := range vector[:i] {
			require.False(t, vector[i].Equal(&vector[j]), "elements %d and %d collided", j, i)
		}
	}
}

func TestVectorE6Sum(t *testing.T) {
	var zero E6
	var nilVector VectorE6
	require.Equal(t, zero, nilVector.Sum())

	for _, size := range []int{0, 1, 2, 3, 15, 16, 17, 33, 100, 1 << 12} {
		t.Run(strconv.Itoa(size), func(t *testing.T) {
			v := make(VectorE6, size)
			v.MustSetRandom()

			// the sum is the inner product with ones
			ones := make(VectorE6, size)
			for i := range ones {
				ones[i].SetOne()
			}
			require.Equal(t, v.InnerProduct(ones), v.Sum())

			// size copies of x sum to x multiplied by size, as an element of the base field
			var x E6
			x.MustSetRandom()
			xs := make(VectorE6, size)
			for i := range xs {
				xs[i] = x
			}
			var n fr.Element
			n.SetUint64(uint64(size))
			var expected E6
			expected.MulByElement(&x, &n)
			require.Equal(t, expected, xs.Sum())
		})
	}
}

func TestVectorE6ElementwiseOps(t *testing.T) {
	const size = 17
	a := make(VectorE6, size)
	a.MustSetRandom()
	var c fr.Element
	c.MustSetRandom()
	b := make(VectorE6, size)
	b.MustSetRandom()
	add, sub, mul := make(VectorE6, size), make(VectorE6, size), make(VectorE6, size)
	add.Add(a, b)
	sub.Sub(a, b)
	mul.Mul(a, b)

	neg, scalarAdd, scalarSub, subFrom := make(VectorE6, size), make(VectorE6, size), make(VectorE6, size), make(VectorE6, size)
	neg.Neg(a)
	scalarAdd.ScalarAddElement(a, &c)
	scalarSub.ScalarSubElement(a, &c)
	subFrom.ScalarSubFromElement(&c, a)

	for i := range a {
		var e E6
		require.Equal(t, *e.Add(&a[i], &b[i]), add[i])
		require.Equal(t, *e.Sub(&a[i], &b[i]), sub[i])
		require.Equal(t, *e.Mul(&a[i], &b[i]), mul[i])
		require.Equal(t, *e.Neg(&a[i]), neg[i])
		require.Equal(t, *e.AddElement(&a[i], &c), scalarAdd[i])
		require.Equal(t, *e.SubElement(&a[i], &c), scalarSub[i])
		require.Equal(t, *e.SubFromElement(&c, &a[i]), subFrom[i])
	}

	// the destination may alias a
	aliased := make(VectorE6, size)
	copy(aliased, a)
	aliased.Neg(aliased)
	require.Equal(t, neg, aliased)

	// the scalar may alias an element of the destination
	c0 := a[0].B0.A0
	v := make(VectorE6, size)
	for _, op := range []struct {
		name    string
		vector  func(v VectorE6, c *fr.Element)
		element func(z, x *E6, c *fr.Element)
	}{
		{"ScalarAddElement", func(v VectorE6, c *fr.Element) { v.ScalarAddElement(v, c) }, func(z, x *E6, c *fr.Element) { z.AddElement(x, c) }},
		{"ScalarSubElement", func(v VectorE6, c *fr.Element) { v.ScalarSubElement(v, c) }, func(z, x *E6, c *fr.Element) { z.SubElement(x, c) }},
		{"ScalarSubFromElement", func(v VectorE6, c *fr.Element) { v.ScalarSubFromElement(c, v) }, func(z, x *E6, c *fr.Element) { z.SubFromElement(c, x) }},
	} {
		copy(v, a)
		op.vector(v, &v[0].B0.A0)
		for i := range a {
			var e E6
			op.element(&e, &a[i], &c0)
			require.Equal(t, e, v[i], op.name)
		}
	}
}

func TestVectorE6ButterflyPair(t *testing.T) {
	for _, size := range []int{2, 4, 8, 16, 18} {
		t.Run(strconv.Itoa(size), func(t *testing.T) {
			a := make([]E6, size)
			for i := range a {
				setE6TestValue(&a[i], uint64(i*8+1))
			}
			expected := append([]E6(nil), a...)
			for i := 0; i < len(expected); i += 2 {
				ButterflyE6(&expected[i], &expected[i+1])
			}

			VectorE6(a).ButterflyPair()
			for i := range expected {
				require.Equal(t, expected[i], a[i], "element %d", i)
			}
		})
	}
}

func TestVectorE6FusedTwiddles(t *testing.T) {
	for _, size := range []int{2, 4, 8, 16, 18} {
		t.Run(strconv.Itoa(size), func(t *testing.T) {
			a0, a1, twiddles := makeE6FusedTestInputs(size)

			expected0 := append([]E6(nil), a0...)
			expected1 := append([]E6(nil), a1...)
			for i := range expected0 {
				expected1[i].MulByElement(&expected1[i], &twiddles[i])
				ButterflyE6(&expected0[i], &expected1[i])
			}

			VectorE6(a0).MulByElementThenButterfly(VectorE6(a1), twiddles)
			require.Equal(t, expected0, a0)
			require.Equal(t, expected1, a1)

			a0, a1, twiddles = makeE6FusedTestInputs(size)
			expected0 = append([]E6(nil), a0...)
			expected1 = append([]E6(nil), a1...)
			for i := range expected0 {
				ButterflyE6(&expected0[i], &expected1[i])
				expected1[i].MulByElement(&expected1[i], &twiddles[i])
			}

			VectorE6(a0).ButterflyThenMulByElement(VectorE6(a1), twiddles)
			require.Equal(t, expected0, a0)
			require.Equal(t, expected1, a1)
		})
	}
}

